class Solution {
public:
    int alternatingSubarray(vector<int>& nums) {
        int n = nums.size(), answer = -1;
        for (int i = 0; i + 1 < n; ++i) {
            int expected = 1;
            for (int j = i + 1; j < n; ++j) {
                if (nums[j] - nums[j - 1] != expected) break;
                answer = max(answer, j - i + 1);
                expected = -expected;
            }
        }
        return answer;
    }
};
